/* Global */
const themeToggle=document.getElementById('theme-toggle');if(themeToggle){themeToggle.addEventListener('click',()=>{const currentTheme=document.documentElement.getAttribute('data-theme');const newTheme=currentTheme==='dark'?'light':'dark';document.documentElement.setAttribute('data-theme',newTheme);localStorage.setItem('smart-dps-theme',newTheme);themeToggle.innerHTML=newTheme==='dark'?'<i class="fas fa-sun"></i>':'<i class="fas fa-moon"></i>';});}
const savedTheme=localStorage.getItem('smart-dps-theme')||localStorage.getItem('free-sms-theme');if(savedTheme){document.documentElement.setAttribute('data-theme',savedTheme);if(themeToggle)themeToggle.innerHTML=savedTheme==='dark'?'<i class="fas fa-sun"></i>':'<i class="fas fa-moon"></i>';}function openModal(modalId){const modal=document.getElementById(modalId);if(modal){modal.classList.add('active');document.body.style.overflow='hidden';}}function closeModal(modalId){const modal=document.getElementById(modalId);if(modal){modal.classList.remove('active');document.body.style.overflow='auto';}}function openDeleteModal(contactId){const modal=document.getElementById('delete-modal');if(modal){modal.setAttribute('data-contact-id',contactId);modal.classList.add('active');document.body.style.overflow='hidden';}}function confirmDelete(){const modal=document.getElementById('delete-modal');const contactId=modal.getAttribute('data-contact-id');showToast(`Contact ${contactId}deleted successfully.`);closeModal('delete-modal');const row=document.querySelector(`tr[data-id="${contactId}"]`);if(row)row.remove();}function searchTemplates(query){const container=document.getElementById('template-list-container');if(!container)return;const filtered=smsTemplates.filter(t=>t.name.toLowerCase().includes(query.toLowerCase())||t.text.toLowerCase().includes(query.toLowerCase()));renderTemplates(filtered);}function renderTemplates(templates){const container=document.getElementById('template-list-container');if(!container)return;container.innerHTML=templates.map(t=>{const safeText=t.text.replace(/'/g,"\\'").replace(/"/g,'&quot;');return`<div class="template-item"onclick="selectTemplate(${t.id}, '${safeText}')"><div class="template-name">${t.name}</div><div class="template-preview">${t.text}</div></div>`;}).join('');}function searchContacts(query){const container=document.getElementById('contact-list-container');if(!container)return;const filtered=savedContacts.filter(c=>c.name.toLowerCase().includes(query.toLowerCase())||c.number.includes(query));renderContacts(filtered);}function renderContacts(contacts){const container=document.getElementById('contact-list-container');if(!container)return;container.innerHTML=contacts.map(c=>`<div class="contact-item"onclick="selectContact(${c.id}, '${c.number}')"><div class="contact-avatar">${c.name.charAt(0)}</div><div class="contact-info"><div class="contact-name">${c.name}</div><div class="contact-number">${c.code}${c.number}</div></div></div>`).join('');}if(typeof window.selectTemplate!=='function'){window.selectTemplate=function(id,text){const textarea=document.getElementById('sms-message');if(textarea){textarea.value=text;const count=document.getElementById('char-count');if(count)count.textContent=text.length;}closeModal('template-modal');};}if(typeof window.selectContact!=='function'){window.selectContact=function(id,number){const numberInput=document.getElementById('phone-number');if(numberInput)numberInput.value=number;closeModal('contact-modal');};}document.addEventListener('DOMContentLoaded',()=>{renderTemplates(smsTemplates);renderContacts(savedContacts);});function showToast(message,duration=3000){let toast=document.getElementById('global-toast');if(!toast){toast=document.createElement('div');toast.id='global-toast';toast.className='toast';document.body.appendChild(toast);}toast.textContent=message;toast.style.display='block';setTimeout(()=>{toast.style.display='none';},duration);}